package com.example.starter.ventilation;

/**
 * 火灾模式生命周期状态。
 */
public enum ModeStatus {
    /** 已激活，排烟联动进行中 */
    ACTIVE,
    /** 火警解除，逆序复位进行中（复位完成前不接受新的激活） */
    RESETTING,
    /** 复位全部完成，等待归档 */
    RESET_COMPLETE,
    /** 归档终态：结论不再被迟到反馈改变 */
    ARCHIVED
}

package com.example.starter.ventilation;

/**
 * 指令所处阶段：排烟联动（先阀后机）或复位（先风机后风阀的逆序）。
 */
public enum CommandPhase {
    PURGE,
    RESET
}

package com.example.starter.ventilation;

/**
 * 设备指令执行状态。
 */
public enum CommandStatus {
    /** 已生成但尚未下发（等待前序设备到位） */
    PENDING,
    /** 已下发，等待到位反馈 */
    ISSUED,
    /** 已收到到位确认 */
    IN_POSITION,
    /** 重发后仍超时：设备故障 */
    FAILED,
    /** 因共享风阀冲突等原因跳过，不下发 */
    SKIPPED
}

package com.example.starter.ventilation;

/**
 * 幂等请求类别。
 */
public enum RequestKind {
    ACTIVATE,
    RESET,
    ARCHIVE,
    FEEDBACK
}

