package com.example.starter.ventilation.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 火灾模式激活请求。
 *
 * @param requestId          激活指令幂等键
 * @param zoneCode           防火分区编码
 * @param smokeFlowDirection 烟气流向假设（合成场景标签，参与指纹）
 * @param targetCondition    目标工况（如 PURGE_MAX 强排烟）
 */
public record ActivateRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 32) String zoneCode,
        @NotBlank @Size(max = 32) String smokeFlowDirection,
        @NotBlank @Size(max = 64) String targetCondition) {
}

package com.example.starter.ventilation.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 火警解除复位请求。
 *
 * @param requestId      复位指令自身的幂等键
 * @param modeRequestId  待复位火灾模式的激活 requestId
 */
public record ResetRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String modeRequestId) {
}

package com.example.starter.ventilation.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 模式归档请求。归档为终态，重复归档返回幂等成功。
 *
 * @param requestId      归档指令自身的幂等键
 * @param modeRequestId  待归档火灾模式的激活 requestId
 */
public record ArchiveRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String modeRequestId) {
}

package com.example.starter.ventilation.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 设备到位反馈（模拟现场机电系统回报，无需真实外部系统）。
 *
 * @param requestId     反馈幂等键
 * @param commandUid    对应设备指令编码
 * @param deviceCode    反馈设备编码
 * @param inPosition    是否到位：true 到位确认；false 尚未到位
 * @param observedState 现场观测状态（可为空，仅记录）
 */
public record FeedbackRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 48) String commandUid,
        @NotBlank @Size(max = 32) String deviceCode,
        @NotNull Boolean inPosition,
        @Size(max = 16) String observedState) {
}

