package com.example.starter.ventilation;

import org.springframework.http.HttpStatus;

/**
 * 业务异常基类：携带对客户端可见的 HTTP 状态码与错误说明。
 */
public class ServiceException extends RuntimeException {

    private final HttpStatus status;

    public ServiceException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus getStatus() {
        return status;
    }
}

package com.example.starter.ventilation;

import org.springframework.http.HttpStatus;

/**
 * 409 冲突：同键异参、分区激活互斥、复位完成前再激活、共享风阀目标冲突等。
 */
public class ConflictException extends ServiceException {

    public ConflictException(String message) {
        super(HttpStatus.CONFLICT, message);
    }
}

package com.example.starter.ventilation;

import org.springframework.http.HttpStatus;

/**
 * 404：指定 requestId 的火灾模式或指令不存在。
 */
public class NotFoundException extends ServiceException {

    public NotFoundException(String message) {
        super(HttpStatus.NOT_FOUND, message);
    }
}

package com.example.starter.ventilation;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;

/**
 * 统一时间来源：生产使用系统时钟，测试可替换为可控时钟以验证 60 秒恰超时。
 * 全部时间以 Asia/Shanghai 落库（DATETIME 不带时区）。
 */
public class TimeService {

    public static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");

    private Clock clock = Clock.system(ZONE);

    public LocalDateTime now() {
        return LocalDateTime.ofInstant(Instant.now(clock), ZONE);
    }

    /** 仅供测试替换时钟。 */
    public void setClock(Clock clock) {
        this.cllockGuard(clock);
    }

    private void cllockGuard(Clock clock) {
        this.clock = clock;
    }
}

