private void afterProgress(FireModeRow mode, String phase, java.time.LocalDateTime now) {
    boolean openBefore = repo.listCommandsByMode(mode.id()).stream()
            .anyMatch(c -> c.phase().equals(phase)
                    && ("PENDING".equals(c.status()) || "ISSUED".equals(c.status())));
    advanceCommands(mode.id(), phase, mode.requestId(), now);
    List<CommandRow> phaseCmds = repo.listCommandsByMode(mode.id()).stream()
            .filter(c -> c.phase().equals(phase)).toList();
    boolean openAfter = phaseCmds.stream()
            .anyMatch(c -> "PENDING".equals(c.status()) || "ISSUED".equals(c.status()));
    if (openBefore && !openAfter && !phaseCmds.isEmpty()) {
        if (PURGE.equals(phase)) {
