repo.insertEvent(mode.id(), mode.zoneCode(), mode.requestId(),
        "ALARM_ESCALATED", "告警升级：分区 " + cmd.zoneCode() + " 设备 "
                + cmd.deviceCode() + " 两次下发均超时，转设备故障并升级告警；"
                + "故障设备不阻塞其他分区指令", now);
return cmd.commandUid();
